class Solution:
    def leastBricks(self, wall: list[list[int]]) -> int:
        width = sum(wall[0])
        best = len(wall)
        for pos in range(1, width):
            crossed = 0
            for row in wall:
                acc = 0
                has_edge = False
                for brick in row[:-1]:
                    acc += brick
                    if acc == pos:
                        has_edge = True
                        break
                    if acc > pos:
                        break
                if not has_edge:
                    crossed += 1
            best = min(best, crossed)
        return best

solutions.better:
class Solution:
    def leastBricks(self, wall):
        edges = []
        for row in wall:
            acc = 0
            for brick in row[:-1]:
                acc += brick
                edges.append(acc)
        if not edges:
            return len(wall)
        edges.sort()
        best = cur = 1
        for i in range(1, len(edges)):
            if edges[i] == edges[i - 1]:
                cur += 1
            else:
                best = max(best, cur)
                cur = 1
        best = max(best, cur)
        return len(wall) - best

