class Solution:
    def leastBricks(self, wall):
        counts = {}
        best_edges = 0
        for row in wall:
            acc = 0
            for brick in row[:-1]:
                acc += brick
                counts[acc] = counts.get(acc, 0) + 1
                best_edges = max(best_edges, counts[acc])
        return len(wall) - best_edges

